// main_tracer.rs - Find all main routines and trace their full dependency trees
// Generated by step4_bootstrap - Main Routine Dependency Tracing

use std::fs;
use std::path::{Path, PathBuf};
use std::collections::{HashMap, HashSet};
use syn::{File, Item, ItemFn, Expr, ExprCall, ExprPath};
use quote::ToTokens;
use walkdir::WalkDir;
use anyhow::Result;

#[derive(Debug, Clone)]
pub struct MainRoutine {
    pub name: String,
    pub file_path: String,
    pub crate_name: String,
    pub dependencies: Vec<String>,
    pub calls: Vec<String>,
}

#[derive(Debug, Clone)]
pub struct DependencyTree {
    pub main_routine: MainRoutine,
    pub reaching_tree: HashMap<String, Vec<String>>, // function -> dependencies
    pub call_graph: HashMap<String, Vec<String>>,    // function -> called functions
    pub total_functions: usize,
}

pub fn find_all_main_routines(rustc_deps: &[crate::DependencyPath]) -> Result<Vec<MainRoutine>> {
    let mut main_routines = Vec::new();
    
    for dep in rustc_deps {
        let rust_files = crate::find_rust_files_in_dependency(&dep.path);
        
        for file_path in rust_files {
            if let Ok(content) = fs::read_to_string(&file_path) {
                if let Ok(parsed) = syn::parse_file(&content) {
                    for item in &parsed.items {
                        if let Item::Fn(func) = item {
                            if func.sig.ident == "main" {
                                let calls = extract_function_calls(&parsed);
                                
                                main_routines.push(MainRoutine {
                                    name: "main".to_string(),
                                    file_path: file_path.to_string_lossy().to_string(),
                                    crate_name: dep.name.clone(),
                                    dependencies: vec![dep.name.clone()],
                                    calls,
                                });
                            }
                        }
                    }
                }
            }
        }
    }
    
    Ok(main_routines)
}

pub fn extract_function_calls(parsed_file: &File) -> Vec<String> {
    let mut calls = Vec::new();
    
    for item in &parsed_file.items {
        if let Item::Fn(func) = item {
            calls.extend(extract_calls_from_function(func));
        }
    }
    
    calls
}

pub fn extract_calls_from_function(func: &ItemFn) -> Vec<String> {
    let mut calls = Vec::new();
    let func_str = func.to_token_stream().to_string();
    
    // Simple pattern matching for function calls
    for line in func_str.lines() {
        if line.contains("::") && (line.contains("(") || line.contains("!")) {
            // Extract potential function/macro calls
            let words: Vec<&str> = line.split_whitespace().collect();
            for word in words {
                if word.contains("::") && (word.contains("(") || word.contains("!")) {
                    let call = word.split('(').next().unwrap_or(word)
                                  .split('!').next().unwrap_or(word)
                                  .trim_end_matches(',')
                                  .trim_end_matches(';');
                    if !call.is_empty() && call.len() > 2 {
                        calls.push(call.to_string());
                    }
                }
            }
        }
    }
    
    calls
}

pub fn build_reaching_tree(main_routine: &MainRoutine, all_deps: &[crate::DependencyPath]) -> Result<DependencyTree> {
    let mut reaching_tree = HashMap::new();
    let mut call_graph = HashMap::new();
    let mut visited = HashSet::new();
    let mut total_functions = 0;
    
    // Start with main routine
    reaching_tree.insert("main".to_string(), main_routine.calls.clone());
    call_graph.insert("main".to_string(), main_routine.calls.clone());
    
    // Trace each dependency recursively
    for dep in all_deps {
        if let Ok(functions) = extract_all_functions_from_dependency(&dep.path) {
            total_functions += functions.len();
            
            for (func_name, func_calls) in functions {
                if !visited.contains(&func_name) {
                    reaching_tree.insert(func_name.clone(), func_calls.clone());
                    call_graph.insert(func_name.clone(), func_calls);
                    visited.insert(func_name);
                }
            }
        }
    }
    
    Ok(DependencyTree {
        main_routine: main_routine.clone(),
        reaching_tree,
        call_graph,
        total_functions,
    })
}

pub fn extract_all_functions_from_dependency(dep_path: &str) -> Result<HashMap<String, Vec<String>>> {
    let mut functions = HashMap::new();
    let rust_files = crate::find_rust_files_in_dependency(dep_path);
    
    for file_path in rust_files {
        if let Ok(content) = fs::read_to_string(&file_path) {
            if let Ok(parsed) = syn::parse_file(&content) {
                for item in &parsed.items {
                    if let Item::Fn(func) = item {
                        let func_name = func.sig.ident.to_string();
                        let calls = extract_calls_from_function(func);
                        functions.insert(func_name, calls);
                    }
                }
            }
        }
    }
    
    Ok(functions)
}

#[macro_export]
macro_rules! mkmain_trees {
    () => {{
        let rustc_deps = get_rustc_dependencies().unwrap_or_default();
        let main_routines = find_all_main_routines(&rustc_deps).unwrap_or_default();
        
        let mut trees = Vec::new();
        for main_routine in main_routines {
            if let Ok(tree) = build_reaching_tree(&main_routine, &rustc_deps) {
                trees.push(tree);
            }
        }
        
        trees
    }};
}

#[macro_export]
macro_rules! mkfull_main_analysis {
    () => {{
        let trees = mkmain_trees!();
        
        println!("🔍 MAIN ROUTINE ANALYSIS:");
        println!("  📊 Found {} main routines", trees.len());
        
        for (i, tree) in trees.iter().enumerate() {
            println!("\n🎯 Main #{}: {} in {}", 
                     i+1, tree.main_routine.name, tree.main_routine.crate_name);
            println!("  📄 File: {}", tree.main_routine.file_path);
            println!("  🔧 Total functions in tree: {}", tree.total_functions);
            println!("  📞 Direct calls: {}", tree.main_routine.calls.len());
            println!("  🌳 Reaching tree size: {}", tree.reaching_tree.len());
            
            if !tree.main_routine.calls.is_empty() {
                println!("  📝 Sample calls:");
                for call in tree.main_routine.calls.iter().take(5) {
                    println!("    → {}", call);
                }
            }
        }
        
        trees
    }};
}
